-- These algorithms are authored here, not generated by the host.
plum.require_api(0, 2)
local function integer(value, low, high)
  assert(math.type(value) == "integer" and value >= low and value <= high)
  return value
end
function register(p)
  p.service{id="pattern", version="1.0", run=function(data, ctx)
    local count = integer(data.count, 1, 128)
    local start = integer(data.start, 0, 1000000000000)
    local spacing = integer(data.spacing, 1, 1000000)
    local gate = integer(data.gate, 1, 1000000)
    local max_key = integer(data.max_key, 127, 255)
    local base_key = integer(data.base_key, 0, max_key)
    local velocity = integer(data.velocity, 1, 127)
    local steps = {0, 2, 4, 7, 9, 7, 4, 2}
    local state, notes = ctx.seed & 0x7fffffff, {}
    for i = 0, count - 1 do
      state = (1103515245 * state + 12345) & 0x7fffffff
      notes[#notes + 1] = {start=start + i * spacing, gate=gate,
        key=math.min(max_key, base_key + steps[i % #steps + 1]),
        velocity=math.max(1, math.min(127, velocity + state % 7 - 3)), channel=0}
    end
    return {notes=notes}
  end}
  p.service{id="transform", version="1.0", run=function(data)
    local columns, notes = data.columns, {}
    local shift = integer(data.transpose, -255, 255)
    local max_key = integer(data.max_key, 127, 255)
    assert(#columns.start <= 32)
    local fields = {"start", "gate", "key", "velocity", "channel", "subchannel",
      "muted", "off_kind", "off_velocity", "group"}
    for i = 1, #columns.start do
      local row = {}
      for _, field in ipairs(fields) do
        if columns[field] then row[field] = columns[field][i] end
      end
      row.key = math.max(0, math.min(max_key, row.key + shift))
      notes[#notes + 1] = row
    end
    return {notes=notes}
  end}
end
